<script lang="ts">
import {onMount} from 'svelte';import {exportFeedback} from './export-feedback';import Icon from './Icon.svelte';import {loadPublicAchievement,achievementExport,type PublicAchievement} from './bridge';import {renderCard,pngBytes} from './achievement-card';
let {profile,achievement,network,t,language,dark,onclose}:{profile:string;achievement:string;network:string;t:(key:string)=>string;language:string;dark:boolean;onclose:()=>void}=$props();
let dialog:HTMLDialogElement;let mode=$state('text');let text=$state('');let model=$state<PublicAchievement|null>(null);let card=$state<HTMLCanvasElement|null>(null);let preview=$state<HTMLCanvasElement>();let failed=$state(false);let busy=$state(false);let result=$state('');
const names:Record<string,string>={telegram:'Telegram',x:'X',facebook:'Facebook',instagram:'Instagram'};
onMount(()=>{dialog.showModal();let current=true;loadPublicAchievement(profile,achievement,language).then(async value=>{const image=await renderCard(value.card,dark);if(current){model=value;text=value.post;card=image;}}).catch(()=>{if(current)failed=true;});return()=>{current=false;dialog.close();};});
$effect(()=>{if(mode==='card'&&preview&&card){preview.width=1200;preview.height=900;preview.getContext('2d')?.drawImage(card,0,0);}});
async function prepare(){if(!model||busy)return;busy=true;failed=false;try{const request=mode==='text'?{action:'prepare_text',network,text}:{action:'prepare_image',network,png:await pngBytes(card!)};const value=await achievementExport(profile,achievement,language,request);result=exportFeedback(value);}catch{failed=true;}finally{busy=false;}}
async function showFile(){try{await achievementExport(profile,achievement,language,{action:'show_image'});}catch{failed=true;}}
</script>
<dialog class="share-dialog" bind:this={dialog} oncancel={e=>{e.preventDefault();if(!busy)onclose();}}><h2><Icon name="share"/>{t('Поделиться достижением')} · {names[network]}</h2><div class="share-modes" role="group" aria-label={t('Формат публикации')}>{#each [['text','Текст','text'],['card','Карточка','calendar']] as [id,label,icon]}<button class:chosen={mode===id} aria-pressed={mode===id} disabled={busy} onclick={()=>{mode=id;result='';}}><Icon name={icon}/>{t(label)}</button>{/each}</div>
{#if model}{#if mode==='text'}<textarea aria-label={t('Текст публикации')} bind:value={text} maxlength="16384" spellcheck="false"></textarea>{:else}<div class="share-card-preview"><canvas bind:this={preview} aria-label={t('Карточка достижения')}></canvas></div>{/if}<p class="muted help">{t(mode==='text'?'Скопируем текст и откроем соцсеть. Останется вставить его в пост.':'Сохраним PNG и откроем соцсеть. Останется прикрепить файл к посту.')}</p><p class="muted help">{t('Только статистика — без данных записи.')}</p>{:else if !failed}<p class="muted">{t('Загрузка…')}</p>{/if}
{#if failed}<p class="error" role="alert">{t('Не удалось подготовить публикацию')}</p>{/if}{#if result}<div class="share-result" role="status"><strong>{t(result==='text_prepared'?'Текст скопирован':'Карточка подготовлена')}</strong><p>{t(result==='text_prepared'?'Вставить текст в публикацию и подтвердить отправку. Если требуется фото — прикрепить карточку.':'Создать публикацию, прикрепить подготовленный PNG и подтвердить отправку.')}</p>{#if result==='image_prepared'}<button onclick={()=>void showFile()}><Icon name="folder"/>{t('Показать файл')}</button>{/if}</div>{/if}
<div class="share-actions"><button disabled={busy} onclick={onclose}>{t('Закрыть')}</button><button class="primary" disabled={!model||busy} onclick={()=>void prepare()}><Icon name="external"/>{t('Подготовить и открыть')} {names[network]}</button></div></dialog>
<style>.share-dialog{width:min(620px,calc(100vw - 32px));max-height:calc(100vh - 32px);padding:22px;background:var(--bg);color:var(--text);border:1px solid var(--strong);border-radius:12px;overflow:auto}.share-dialog::backdrop{background:#0008}h2{display:flex;align-items:center;gap:10px;font-size:18px;margin:0 0 16px}.share-modes{display:flex;gap:8px;margin-bottom:14px}.share-modes .chosen{background:var(--selection);border-color:var(--accent);color:var(--accent-text)}textarea{width:100%;height:260px;background:var(--surface);border:1px solid var(--strong);border-radius:7px;padding:12px;color:var(--text);font:inherit;resize:vertical;outline:none}textarea:focus{border-color:var(--accent)}.share-card-preview{height:300px;display:flex;justify-content:center}.share-card-preview canvas{height:100%;width:auto;max-width:100%;object-fit:contain;border:1px solid var(--line);border-radius:6px}.help{font-size:12px;line-height:1.45;margin:10px 0}.share-actions{display:flex;justify-content:space-between;gap:10px;margin-top:18px}.primary{color:white;background:var(--accent);border-color:var(--accent)}.share-result{padding:12px;border:1px solid var(--line);border-radius:7px;background:var(--surface)}.share-result p{font-size:12px;margin:7px 0}.share-result button{font-size:12px;padding:6px 10px}</style>
